import pandas as pd
import re
import random

def task_func(s: str, seed: int = 0) -> pd.DataFrame:
    products_list = ['Apple', 'Banana', 'Orange', 'Pear', 'Grape']
    rng = random.Random(seed)

    rows = []
    for line in s.splitlines():
        if not line.strip():
            continue

        parts = re.split(r'\s+', line.strip(), maxsplit=4)
        if len(parts) != 5:
            continue

        id_val, qty_val, code_val, price_val, desc_val = parts
        rows.append([
            id_val.rstrip(),
            int(qty_val.rstrip()),
            code_val.rstrip(),
            int(price_val.rstrip()),
            desc_val.rstrip()
        ])

    columns = ['ID', 'Quantity', 'Code', 'Price', 'Product', 'Description']
    if not rows:
        return pd.DataFrame(columns=columns).astype({'Quantity': 'int64', 'Price': 'int64'})

    df = pd.DataFrame(rows, columns=['ID', 'Quantity', 'Code', 'Price', 'Description'])

    code_to_product = {
        code: rng.choice(products_list)
        for code in df['Code'].unique()
    }
    df['Product'] = df['Code'].map(code_to_product)

    return df[columns]
